const SZE = 100;
const S_H = SZE * 0.5;
// https://colorpalettes.net/color-palette-979/
const CLRS = ["#960f16", "#d64d55", "#94c8d6", "#35838d", "#012e33"];

let zoom = {x: 0, y:0, img: null, fc: -1};
let bg

function setup() {
	createCanvas(windowWidth, windowHeight);
	describe("pattern of flowers consisting of arcs randomly rotated by 90 degrees forming a pattern in an ordered grid")
	pixelDensity(1);
	if (false) {
		CLRS.push(color("darkred"))
		CLRS.push(lerpColor(color("cyan"), color("blue"), 0.125))
		CLRS.push(lerpColor(color("darkcyan"), color("darkblue"), 0.125))
	}
	frameRate(30)
	background(212);
	imageMode(CENTER)
}

function draw() {
	if (bg) image(bg, 0, 0, width, height-1)
	const x = ~~(random(width) / SZE) * SZE + S_H;
	const y = ~~(random(width) / SZE) * SZE + S_H;

	let scl = 1;
	if (random() < 0.1 && zoom && !zoom.img) {
		scl = ~~random(2, 4);
		zoom.x = x; 
		zoom.y = y;
		zoom.img = get(x - S_H * scl, y - S_H * scl, SZE * scl, SZE * scl)
		zoom.fc = frameCount + 10 * ~~random(2, 5);
	}
	drawFigure(x, y, SZE * scl);

	if (zoom && zoom.img) {
		if (frameCount < zoom.fc) {
			// keep zoomed flower
		} else {
			// restore stored flowers
			// console.log(zoom);
			image(zoom.img, zoom.x, zoom.y)
			zoom.img = null;
		}
	}

	// bg = get(0, 0, width, height)
}

function mousePressed() {
	if (mouseButton === LEFT) setup();
}

function drawFigure(x, y, SZE) {
	var S_H = SZE / 2;

	push();
	translate(x, y);
	rotate(~~(noise(x, y, frameCount * 0.0004) * 4) * HALF_PI);
	stroke(212);
	strokeWeight(SZE * 0.025);

	if (random() < 0.25) {		
		fill(212)
		rectMode(CENTER)
		rect(0, 0, SZE)
	}

	// arc(x, y, w, h, start, stop, [mode], [detail])

	fill(random(CLRS)) // ["darkred", "green", "darkgreen"]
	arc(-S_H, 0, SZE, SZE, TWO_PI - HALF_PI, TWO_PI, PIE);

	if (random() < 0.1) fill(random(CLRS))
	arc(S_H, 0, SZE, SZE, PI, PI + HALF_PI, PIE);

	if (random() < 0.25) fill(random(CLRS))	
	arc(0, 0, SZE, SZE, 0, HALF_PI, PIE);

	if (random() < 0.1) fill(random(CLRS))
	arc(0, 0, SZE, SZE, HALF_PI, PI, PIE);
	pop();
}

